class Vehicle:
    def __init__(self, brand, speed=0):
        self.brand = brand
        self.speed = speed

    def describe(self):
        return f"{self.brand} moving at {self.speed} km/h"


class Car(Vehicle):
    def __init__(self, brand, model, speed=0):
        super().__init__(brand, speed)
        self.model = model

    def describe(self):
        return super().describe() + f" — Model: {self.model}"


my_car = Car("Tesla", "Model 3 Ashish", 50)
print(my_car.describe())
